   remaining=None; deadline=time.monotonic()+5
   while remaining!='0':
    remaining=subprocess.check_output([str(pg/'psql'),'-h','127.0.0.1','-p',str(port),'-d','postgres','-Atc',"SELECT count(*) FROM pg_stat_activity WHERE application_name='asyncara_fatal_control'"],text=True,timeout=5).strip()
    if remaining!='0' and time.monotonic()>deadline:raise RuntimeError('session retained')
    if remaining!='0':time.sleep(.01)
   text=log.read_text();loss={key:int(re.findall(key+r': ([0-9,]+) bytes',text)[-1].replace(',',''))for key in ['definitely lost','indirectly lost','possibly lost','still reachable']}
   rows.append({'name':tag,'exit':code,'seconds':time.monotonic()-start,'remainingSessions':0,'loss':loss,'command':cmd,'environment':{k:v for k,v in env.items()if k.startswith('ASYNCARA_')or k in ['USE_ZEND_ALLOC','VALGRIND_LIB']},'moduleSha256':sha(module),'sourceManifest':{str(f.relative_to(source)):sha(f)for f in(source/'src').rglob('*.php')},'logSha256':sha(log)})
